        { "id": 24, "daily": "reply", "name": "知識引用", "tagline": "材料面板的「知識與指引」段：引用保留版本掛為案件依據；問題版本會被擋。", "setup": { "route": "workspace" }, "setupLabel": "營運工作台 · 客服 1", "steps": ["在材料面板搜尋案件知識。", "引用，保留版本掛為依據。", "要轉對客走模板或手寫，不直接張貼內部指引。"] }
